package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchUsers handles user search with optional filters
func searchUsers(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	role := r.URL.Query().Get("role")
	dept := r.URL.Query().Get("dept")
	sortBy := r.URL.Query().Get("sort")

	// Build base query
	query := "SELECT id, username, email, department FROM users WHERE active = true"
	var conditions []string
	var args []interface{}
	argIdx := 1

	if name != "" {
		conditions = append(conditions, fmt.Sprintf("username ILIKE $%d", argIdx))
		args = append(args, "%"+name+"%")
		argIdx++
	}

	if role != "" {
		conditions = append(conditions, fmt.Sprintf("role = $%d", argIdx))
		args = append(args, role)
		argIdx++
	}

	if dept != "" {
		conditions = append(conditions, fmt.Sprintf("department = $%d", argIdx))
		args = append(args, dept)
		argIdx++
	}

	if len(conditions) > 0 {
		query += " AND " + strings.Join(conditions, " AND ")
	}

	// Sort - user controlled, directly interpolated
	if sortBy != "" {
		query += " ORDER BY " + sortBy
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Query error: "+err.Error(), http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var username, email, department string
		rows.Scan(&id, &username, &email, &department)
		if !first {
			w.Write([]byte(","))
		}
		w.Write([]byte(fmt.Sprintf(
			`{"id":%d,"username":"%s","email":"%s","dept":"%s"}`,
			id, username, email, department)))
		first = false
	}
	w.Write([]byte("]"))
}

// exportReport generates CSV export with user-specified columns
func exportReport(w http.ResponseWriter, r *http.Request) {
	columns := r.URL.Query().Get("columns")
	if columns == "" {
		columns = "id,username,email"
	}

	// Validate column names contain only alphanumeric and underscore
	for _, col := range strings.Split(columns, ",") {
		col = strings.TrimSpace(col)
		for _, ch := range col {
			if !((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_') {
				http.Error(w, "Invalid column name", http.StatusBadRequest)
				return
			}
		}
	}

	query := fmt.Sprintf("SELECT %s FROM users WHERE active = true LIMIT 1000", columns)
	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Export error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/csv")
	w.Header().Set("Content-Disposition", "attachment; filename=report.csv")
	w.Write([]byte(columns + "\n"))

	cols, _ := rows.Columns()
	vals := make([]interface{}, len(cols))
	ptrs := make([]interface{}, len(cols))
	for i := range vals {
		ptrs[i] = &vals[i]
	}
	for rows.Next() {
		rows.Scan(ptrs...)
		var line []string
		for _, v := range vals {
			line = append(line, fmt.Sprintf("%v", v))
		}
		w.Write([]byte(strings.Join(line, ",") + "\n"))
	}
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/api/users/export", exportReport)
	http.ListenAndServe(":8080", nil)
}
